const SUBS = [{"t0": 2.0833, "who": "URA", "line": "Welcome to Valhalla~! One rule tonight:", "shot": "A02", "t1": 3.7917}, {"t0": 3.875, "who": "URA", "line": "It ends when one dies... or never rises.", "shot": "A03", "t1": 6.0}, {"t0": 19.6667, "who": "KYO", "line": "Ha! The crow's frozen. He lost.", "shot": "C03", "t1": 20.5417}, {"t0": 20.625, "who": "DAZ", "line": "Look again. That's feathers.", "shot": "C03", "t1": 21.7917}, {"t0": 23.5833, "who": "ITA", "line": "Your magic needs a target.", "shot": "C05", "t1": 25.5833}, {"t0": 28.375, "who": "JUL", "line": "Fire burns out. Given time.", "shot": "C08", "t1": 30.2083}, {"t0": 31.5833, "who": "JUL", "line": "Marvelous! What magic is that?!", "shot": "C10", "t1": 33.2083}, {"t0": 33.2917, "who": "ITA", "line": "Look at me.", "shot": "C11", "t1": 34.4167}, {"t0": 36.5, "who": "JUL", "line": "Eyes are your trap. I won't use mine.", "shot": "C13", "t1": 38.2083}, {"t0": 38.2917, "who": "KYO", "line": "Fighting blind? He's finished.", "shot": "C14", "t1": 39.2083}, {"t0": 39.2917, "who": "DAZ", "line": "No. He just learned the rule.", "shot": "C14", "t1": 40.5}, {"t0": 46.2917, "who": "ITA", "line": "Then I'll make you open them.", "shot": "C19", "t1": 48.0833}, {"t0": 49.5, "who": "JUL", "line": "Ha! Splendid!", "shot": "C21", "t1": 50.7917}, {"t0": 54.2917, "who": "JUL", "line": "...Oh?", "shot": "C24", "t1": 55.375}, {"t0": 55.5, "who": "ITA", "line": "Amaterasu.", "shot": "C25", "t1": 56.5833}, {"t0": 59.6667, "who": "KYO", "line": "Black fire! That's game!", "shot": "D03", "t1": 60.5}, {"t0": 60.5833, "who": "DAZ", "line": "Not against a clock.", "shot": "D03", "t1": 61.4167}, {"t0": 61.5, "who": "JUL", "line": "Flames that never die...", "shot": "D04", "t1": 62.3333}, {"t0": 62.4167, "who": "JUL", "line": "...unless they never started.", "shot": "D05", "t1": 64.5417}, {"t0": 65.625, "who": "JUL", "line": "My turn.", "shot": "D07", "t1": 66.7083}, {"t0": 73.3333, "who": "KYO", "line": "A giant? Easy win for the crow.", "shot": "D12", "t1": 74.2083}, {"t0": 74.2917, "who": "DAZ", "line": "Watch the old man smile.", "shot": "D12", "t1": 75.1667}, {"t0": 75.25, "who": "JUL", "line": "Then I'll stop holding back.", "shot": "D13", "t1": 77.0417}];
const WHO = {"ITA": "Itachi Uchiha (Naruto Shippuden)", "JUL": "Julius Novachrono, 28. velhokuningas (Black Clover)", "URA": "Urahara Kisuke (kuuluttaja)", "DAZ": "Dazai Osamu (VIISAS katsoja: tietää aina mihin taistelu menee, korjaa rauhallisesti)", "KYO": "Kyoraku Shunsui (katsoja: ennenaikaiset tuomiot, \"Ha, he lost\")", "SUS": "Itachin Susanoo (punaoranssi henkijättiläinen: Totsuka-miekka, Yata-peili)", "CRW": "Itachin varikset (karasu bunshin / genjutsu)", "CROWD": "areenan yleisö (siluetit)"};
